#include <stdio.h>

int main(void) {
    int n = 4;
    /* Upper Wings */
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= i; j++) printf("*");
        for (int s = 1; s <= 2 * (n - i); s++) printf(" ");
        for (int j = 1; j <= i; j++) printf("*");
        printf("\n");
    }
    /* Lower Wings */
    for (int i = n; i >= 1; i--) {
        for (int j = 1; j <= i; j++) printf("*");
        for (int s = 1; s <= 2 * (n - i); s++) printf(" ");
        for (int j = 1; j <= i; j++) printf("*");
        printf("\n");
    }
    return 0;
}

#include <stdio.h>

#define MIN(a, b) (((a) < (b)) ? (a) : (b))

int main(void) {
    int n = 4;
    int size = 2 * n - 1;
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < size; j++) {
            int top = i;
            int left = j;
            int bottom = size - 1 - i;
            int right = size - 1 - j;
            int minDist = MIN(MIN(top, bottom), MIN(left, right));
            printf("%d ", n - minDist);
        }
        printf("\n");
    }
    return 0;
}
